def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    low_budget_opps = 0
    desperate_opps = 0
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) <= DAILY_SALARY * 1.2:
                low_budget_opps += 1
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_opps += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))

    if not alive:
        return float(min(budget, DAILY_SALARY * 0.25))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    lowest_prev = min(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    critical = hp <= 2 or no_water >= 2
    urgent = hp <= 4 or no_water >= 1
    abundant = supply >= 22
    tight = supply <= 17

    if critical:
        bid = max(DAILY_SALARY * 1.15, highest_prev + 3.0)
        if abundant:
            bid = max(DAILY_SALARY * 0.95, avg_prev + 2.0)
        return float(min(budget, bid))

    if urgent:
        if tight:
            bid = max(DAILY_SALARY * 0.95, highest_prev + 2.0)
        else:
            bid = max(DAILY_SALARY * 0.78, avg_prev + 1.5)
        return float(min(budget, bid))

    if abundant:
        if low_budget_opps >= 2:
            bid = max(DAILY_SALARY * 0.48, lowest_prev + 1.0)
        else:
            bid = max(DAILY_SALARY * 0.58, avg_prev * 0.82)
        return float(min(budget, bid))

    if tight:
        if highest_prev >= 170:
            bid = DAILY_SALARY * 0.22
        elif highest_prev >= 120:
            bid = DAILY_SALARY * 0.32
        else:
            bid = max(DAILY_SALARY * 0.42, highest_prev + 1.0)
        if desperate_opps >= 2:
            bid *= 0.9
        return float(min(budget, bid))

    bid = DAILY_SALARY * 0.5
    if highest_prev > 0:
        if highest_prev <= DAILY_SALARY * 0.8:
            bid = max(bid, highest_prev + 1.5)
        elif highest_prev >= 160:
            bid = DAILY_SALARY * 0.3
        else:
            bid = max(DAILY_SALARY * 0.45, avg_prev * 0.7)

    if day >= 8 and budget > DAILY_SALARY * 2.5 and hp >= 5:
        bid = max(bid, DAILY_SALARY * 0.62)

    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Immediate reaction from yesterday trace
    prev_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    second_prev_bid = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest_prev_bid

    # Supply pressure: fewer units means higher chance others overbid.
    # Estimate how many water units we can buy if we win with a typical bid.
    # (We don't know conversion; we use relative supply to decide aggressiveness.)
    supply_ratio = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY > MIN_SUPPLY else 0.5
    low_supply = supply_ratio < 0.35

    # Decide baseline aggressiveness
    # If my hp is critical or I've gone several days without water, I must secure water.
    if hp <= 2.0 or no_water_days >= 2:
        # Escalate but cap to avoid matching the aggressive winners.
        target = DAILY_SALARY * (0.75 if low_supply else 0.65)
    else:
        # Stay moderate; only slightly react to their spikes.
        # If they were bidding extremely high yesterday, avoid bidding that high.
        if highest_prev_bid >= DAILY_SALARY * 1.9:
            target = DAILY_SALARY * (0.45 if not low_supply else 0.55)
        else:
            target = DAILY_SALARY * (0.5 if not low_supply else 0.6)

    # Add a small nudge based on their yesterday behavior, but don't chase it.
    # If their highest bid was not too extreme, we can outbid slightly.
    if highest_prev_bid > 0 and highest_prev_bid < DAILY_SALARY * 1.8:
        target = max(target, min(budget, second_prev_bid + 2.0))

    # Final clamp
    if budget <= 0:
        return 0.0
    bid = max(0.0, min(budget, target))
    return float(bid)
